/**
 * The Worker entry (wrangler.jsonc `main`). It runs the CAPTCHA wall (PORTAL-STANDARD §10) first and
 * only then hands the request to the OpenNext worker that `opennextjs-cloudflare build` generates. With
 * `assets.run_worker_first: true`, every path and method comes here first, static files included:
 * OpenNext serves `.open-next/assets` (`_next/static`, `public/`) from inside its own routing, after
 * the wall. The order and the hooks are in src/worker/captcha.ts.
 */
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build` (it doesn't exist before the first build).
import openNextWorker from "./.open-next/worker.js";
import { createCaptcha, handleRequest, type AppWorker } from "./src/worker/captcha";

const openNext = openNextWorker as AppWorker;
const captcha = createCaptcha();

export default {
  fetch: (request, env, ctx) => handleRequest(captcha, openNext, request, env, ctx),
} satisfies ExportedHandler<CloudflareEnv>;
